// Comparison spec for the MC-10 / Alice (6803). diag.asm (generated by gen-diag.js) is our own 8K
// firmware in place of the mc10.rom/alice.rom, with the 16K RAM expansion fitted and two keys held from
// power-on. The CPU runs with mameCompat (two MAME bookkeeping artefacts, see js/cpu/cpu6803.js).
const path = require('path');
const { loadEmu, assembleFile, romImage, writeRoms, mameConfigArgs } = require('../lib/firmware');
const { workDir } = require('../lib/workdir');
const { REGS_6803: REGS } = require('../lib/regs');

// The keys held from power-on, and where they sit. The Alice's matrix is not the MC-10's (its A is row 1
// bit 2; the MC-10's is row 0 bit 1), so the MAME script that presses them is built from each machine's own
// matrix rather than from fixed port indices: a key held must land on the same wire in both emulators.
const HELD = ['A', 'SHIFT'];
function heldPorts(Emu, profileId) {
  const pos = Emu.keyboards[Emu.profiles[profileId].keyboard];
  return HELD.filter((k) => pos[k]).map((k) => {
    const [row, col] = pos[k];
    // MAME's keyboard is eight ports named pb0..pb7, one per column, with a bit per row; the read ANDs
    // every port whose column strobe is low, and a pressed key pulls its bit low (hence value 1 = pressed)
    return { key: k, tag: `:pb${col}`, mask: 1 << row };
  });
}

function machine(profileId, rom, keys, config = {}) {
  const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
  m.setRoms({ basic: rom });
  m.reset(true);
  for (const k of keys) m.setKey(k, true);
  return m;
}

module.exports = {
  family: 'mc10',
  trace(profileId, { regenerate = true, config = {}, work = workDir(profileId) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const asm = assembleFile(path.join(__dirname, 'diag.asm'), '6803', regenerate && path.join(__dirname, 'gen-diag.js'));
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    const held = heldPorts(Emu, profileId);
    return {
      label: profileId, system: profile.mame, work, seconds: 3, args: mameConfigArgs(resolved),
      regs: REGS, waitOps: [], haltPc: asm.symbols.get('HALT'),
      // hold the same keys in MAME, on the ports and bits this machine's matrix gives them
      luaPrelude: held.map(({ tag, mask }) => `for _, f in pairs(manager.machine.ioport.ports["${tag}"].fields) do
  if (f.mask == 0x${mask.toString(16).toUpperCase()}) then f:set_value(1) end
end`).join('\n'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, HELD.filter((k) => Emu.keyboards[profile.keyboard][k]), config),
      keys: HELD.filter((k) => Emu.keyboards[profile.keyboard][k]),   // held from power-on (host input, not part of a snapshot)
      instructions: 200000,
    };
  },
  // mid-line latch writes swept across the beam (raster.asm, from gen-raster.js; lib/raster.js)
  raster(profileId, { regenerate = true, config = {}, work = workDir(`${profileId}-raster`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const gen = require('./gen-raster');
    if (regenerate) gen.write();                   // raster.asm from gen-raster.js
    const asm = assembleFile(path.join(__dirname, 'raster.asm'), '6803');
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    return {
      label: profileId, system: profile.mame, work, seconds: 6, args: mameConfigArgs(resolved),
      regs: REGS, waitOps: [], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, [], config),
      phaseAddr: 0x8F00, fieldAddr: 0x8F01, file: 'raster.asm', cases: gen.cases, fields: gen.FIELDS, plain: gen.FIELDS - 2,
    };
  },
  // printer firmware (lib/printer.js): the serial printer on port 2 bit 0
  printer(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-printer` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const asm = assembleFile(path.join(__dirname, 'printer.asm'), '6803');
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    return {
      label: profileId, system: profile.mame, work, seconds: 12, args: mameConfigArgs(resolved),
      regs: REGS, waitOps: [], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, [], config),
      instructions: 3000000, doneAddr: 0x4F01, text: 'CLOADM PRINTER TEST, MC-10 SERIAL PORT, 600 BAUD\r\n',
    };
  },
  // the serial port in loopback (serial-loopback.asm; MAME -rs232 loopback): lockstep, then every byte read back
  serial(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-serial` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const asm = assembleFile(path.join(__dirname, 'serial-loopback.asm'), '6803');
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    const data = asm.symbols.get('DATA'), end = asm.symbols.get('DATAEND');
    return {
      label: `${profileId} serial loopback`, system: profile.mame, work, seconds: 3, args: ['-rs232', 'loopback', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: [], haltPc: asm.symbols.get('HALT'),
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      // the loopback is plugged in before the machine is reset, as MAME starts with it
      machine: () => {
        const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
        m.setRoms({ basic: rom }); m.bitBanger.attach('loopback'); m.reset(true);
        return m;
      },
      instructions: 200000,
      result: (m) => {
        const sent = [...rom.slice(data - 0xE000, end - 0xE000)], back = [...m.ram.slice(0x4F11, 0x4F11 + sent.length)];
        return { ok: m.ram[0x4F00] === 0xFF && m.ram[0x4F01] === 0 && sent.every((v, i) => v === back[i]), sent, back };
      },
    };
  },
  // The welcome program's comparison build. The shipping build runs at $5000 in RAM, from a
  // .bin the page loads. MAME cannot do that, and moving the program into the ROM socket would change its
  // absolute addresses, so gen-welcome.js writes welcome-load-<machine>.asm: a loader in the ROM socket that
  // copies the HALTCODE=1 build (its own bytes, as FCB at $F000 in the same image) to $5000 and jumps to it,
  // so both emulators execute the shipped bytes. The comparison halts once the screen is drawn (the HALTCODE
  // flag), so it never calls POLCAT/CHROUT and needs no ROM entry points; it runs with the 20K RAM option the
  // program requires and no keys held. back: the returning visitor's menu (gen-welcome.js --back: GREET 1 and
  // option 5 set by the loader, as the Session sets them).
  welcome(profileId, { regenerate = true, config = {}, back = false, work = workDir(`${profileId}-welcome${back ? '-back' : ''}`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true, ram: 20 }, config));
    if (regenerate) require('child_process').execFileSync('node', [path.join(__dirname, 'gen-welcome.js'), profileId, ...(back ? ['--back'] : [])], { stdio: 'ignore' });
    const asm = assembleFile(path.join(__dirname, `welcome-load-${profileId}${back ? '-back' : ''}.asm`), '6803');
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    // the HALT the program reaches, from the same source assembled with HALTCODE=1 and this machine's flag
    const defs = Object.assign({ HALTCODE: 1, SIX09: 0 }, profileId === 'alice' ? { MC10: 0, ALICE: 1 } : { MC10: 1, ALICE: 0 });
    const prog = Emu.assemble(require('fs').readFileSync(path.join(__dirname, '../../../examples/welcome6803.asm'), 'utf8'), '6803',
      { include: (n) => { const p = path.join(__dirname, '../../../examples', n); return require('fs').existsSync(p) ? require('fs').readFileSync(p, 'utf8') : null; }, defines: defs });
    if (!prog.ok) throw new Error('welcome6803.asm: ' + JSON.stringify(prog.errors));
    return {
      label: `${profileId} welcome6803${back ? ' (back)' : ''}`, system: profile.mame, work, seconds: 6, args: mameConfigArgs(resolved),
      regs: REGS, waitOps: [], haltPc: prog.symbols.get('HALT'), stopAtHalt: true,
      install: () => writeRoms(work, profile.mame, { [profile.roms[0].files[0]]: rom }),
      machine: () => machine(profileId, rom, [], Object.assign({ ram: 20 }, config)),
      instructions: 400000, rom,
    };
  },
  video(profileId) {
    const asm = assembleFile(path.join(__dirname, 'vdg.asm'), '6803');
    const rom = romImage(asm, 0xE000, 0x2000, 0x01);
    return { machine: () => machine(profileId, rom, []), frames: 800 };
  },
};
